import java.io.*;
import java.util.*;

public class Main {
    static BufferedReader in = new BufferedReader(new InputStreamReader(System.in));
    static StringTokenizer tokens = new StringTokenizer("");

    static String next() throws IOException {
        while (!tokens.hasMoreTokens()) {
            tokens = new StringTokenizer(in.readLine());
        }
        return tokens.nextToken();
    }

    public static void main(String[] args) throws IOException {
        long n = Long.parseLong(next());
        long[][] iv = new long[(int) n][2];
        for (int i = 0; i < iv.length; i++) {
            for (int j = 0; j < iv[i].length; j++) {
                iv[i][j] = Long.parseLong(next());
            }
        }

        Arrays.sort(iv, (p, q) -> Long.compare(p[0], q[0]));
        PriorityQueue<Long> heap = new PriorityQueue<>();
        for (long[] meeting : iv) {
            if (!heap.isEmpty() && heap.peek() <= meeting[0]) heap.poll();
            heap.add(meeting[1]);
        }
        System.out.println(heap.size());
    }
}
